
import numpy as np
import matplotlib.pyplot as plt
from pathlib import Path

# Load the dataset generated by Training_data_set.py
dataset_path = Path("data/shapes_dataset.npz")

data = np.load(dataset_path)

# Retrieve training, validation and test data
X_train = data["X_train"]
y_train = data["y_train"]
masks_train = data["masks_train"]

X_val = data["X_val"]
y_val = data["y_val"]
masks_val = data["masks_val"]

X_test = data["X_test"]
y_test = data["y_test"]
masks_test = data["masks_test"]

class_names = data["class_names"].tolist()

# 1. Inspect dimensions and data types
print("TRAINING DATA")
print("Images:", X_train.shape, X_train.dtype)
print("Labels:", y_train.shape, y_train.dtype)
print("Masks:", masks_train.shape, masks_train.dtype)

print("\nVALIDATION DATA")
print("Images:", X_val.shape)
print("Labels:", y_val.shape)
print("Masks:", masks_val.shape)

print("\nTEST DATA")
print("Images:", X_test.shape)
print("Labels:", y_test.shape)
print("Masks:", masks_test.shape)

# 2. Count the number of images in each class
print("\nCLASS DISTRIBUTION")

for class_id, class_name in enumerate(class_names):
    train_count = np.sum(y_train == class_id)
    val_count = np.sum(y_val == class_id)
    test_count = np.sum(y_test == class_id)

    print(
        f"{class_name:10s} | "
        f"Train: {train_count:3d} | "
        f"Validation: {val_count:3d} | "
        f"Test: {test_count:3d}"
    )

# 3. Inspect pixel values and masks
print("\nPIXEL VALUE CHECKS")
print("Image minimum:", X_train.min())
print("Image maximum:", X_train.max())
print("Unique mask values:", np.unique(masks_train))

# 4. Check for empty masks
empty_masks = np.sum(
    masks_train.sum(axis=(1, 2)) == 0
)

print("Empty training masks:", empty_masks)

# 5. Display a sample with its mask
sample_index = 0

fig, axes = plt.subplots(1, 2, figsize=(6, 3))

axes[0].imshow(X_train[sample_index])
axes[0].set_title(
    f"Image: {class_names[y_train[sample_index]]}"
)
axes[0].axis("off")

axes[1].imshow(
    masks_train[sample_index],
    cmap="gray",
    vmin=0,
    vmax=1
)
axes[1].set_title("Ground-truth mask")
axes[1].axis("off")

plt.tight_layout()
plt.show()
